INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'weekly', 'adj.', '/ˈwiːkli/', '每周的;一周一次的', 'During the war Priestley presented a weekly radio programme about daily life.', '战时,普里斯特利主持一档每周一次的广播节目,谈论日常生活。', 'First Snow', 1, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a weekly programme', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'inspector', 'n.', '/ɪnˈspektə/', '检查员;巡视员', 'Priestley is best remembered for his famous play An Inspector Calls.', '普里斯特利最为人铭记的是他著名的剧作《探长来访》。', 'First Snow', 2, 0, 'senior', 'wordlist', 'elective3', 'U6', 'An Inspector Calls', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'insist', 'v.', '/ɪnˈsɪst/', '坚称;坚决认为;坚持要求', 'I must insist that last night''s first fall of snow was a real event.', '我必须坚持说,昨夜的初雪是一件大事。', 'First Snow', 3, 0, 'senior', 'wordlist', 'elective3', 'U6', 'insist that', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'secrecy', 'n.', '/ˈsiːkrəsi/', '保密;秘密状态', 'The very secrecy and quietness of the falling snow made it feel more magical.', '正是落雪的隐秘与安静,让它显得更加神奇。', 'First Snow', 4, 0, 'senior', 'wordlist', 'elective3', 'U6', 'the secrecy of the snow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'shaving', 'n.', '/ˈʃeɪvɪŋ/', '刮胡子', 'The strange morning light made the familiar business of washing and shaving feel new.', '奇异的晨光,让洗漱和刮胡子这些熟悉的事都变得新鲜。', 'First Snow', 5, 0, 'senior', 'wordlist', 'elective3', 'U6', 'washing and shaving', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'flush', 'v.', '/flʌʃ/', '(使)发红;脸红', 'The morning sun began to flush the white snow with delicate pink.', '晨曦开始把白雪染上淡淡的粉色。', 'First Snow', 6, 0, 'senior', 'wordlist', 'elective3', 'U6', 'flush the snow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'plum', 'n.', '/plʌm/', '李子;李树;梅', 'The little plum tree outside stood quietly in the full winter sunlight.', '外面那棵小李树静静地立在冬日的阳光里。', 'First Snow', 7, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a plum tree', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'faintly', 'adv.', '/ˈfeɪntli/', '微弱地;隐约地', 'Soft snow lay faintly along the thin branches of the small tree.', '薄雪隐约地铺在小树细细的枝条上。', 'First Snow', 8, 0, 'senior', 'wordlist', 'elective3', 'U6', 'lie faintly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sparkle', 'n.', '/ˈspɑːk(ə)l/', '闪耀;闪光', 'An hour later everything outside was a cold sparkle of white and blue.', '一个小时后,外面的一切都成了白与蓝的清冷闪光。', 'First Snow', 9, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a cold sparkle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'prospect', 'n.', '/ˈprɒspekt/', '开阔的景色;前景', 'There was something curiously disturbing about the whole white prospect.', '整片白色的景象中有一种奇怪而令人不安的东西。', 'First Snow', 10, 0, 'senior', 'wordlist', 'elective3', 'U6', 'the whole prospect', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'glare', 'n.', '/ɡleə/', '刺眼的强光', 'By noon the bright glare of the snow had completely gone.', '到了中午,雪地刺眼的强光已经完全消失。', 'First Snow', 11, 0, 'senior', 'wordlist', 'elective3', 'U6', 'the glare of the snow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'flake', 'n.', '/fleɪk/', '(雪)小薄片;碎片', 'The snow was now falling in great soft flakes past the window.', '此刻雪正以大片柔软的雪花掠过窗前落下。', 'First Snow', 12, 0, 'senior', 'wordlist', 'elective3', 'U6', 'soft flakes', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bend', 'v.', '/bend/', '(使)弯曲;弯腰', 'The heavy snow made all the trees bend low towards the ground.', '厚厚的积雪把所有的树都压得低低地弯向地面。', 'First Snow', 13, 0, 'senior', 'wordlist', 'elective3', 'U6', 'bend low', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'church', 'n.', '/tʃɜːtʃ/', '教堂', 'The weathercock of the village church could still be seen through the grey air.', '透过灰蒙蒙的空气,仍能看见村庄教堂上的风标。', 'First Snow', 14, 0, 'senior', 'wordlist', 'elective3', 'U6', 'the village church', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'rhyme', 'n.', '/raɪm/', '儿歌;童谣;押韵', 'A childhood rhyme about snow kept running through his head.', '一首关于雪的童年童谣一直在他脑海里回响。', 'First Snow', 15, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a childhood rhyme', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'innocent', 'adj.', '/ˈɪnəs(ə)nt/', '天真无邪的;无辜的', 'The first snow brought back the innocent happiness of his childhood.', '初雪带回了他童年那份天真无邪的快乐。', 'First Snow', 16, 0, 'senior', 'wordlist', 'elective3', 'U6', 'innocent happiness', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'enhance', 'v.', '/ɪnˈhɑːns/', '增强;改进;提高', 'Vivid images can enhance a writer''s description of the first snow.', '生动的意象能增强作家对初雪的描写。', 'First Snow', 17, 0, 'senior', 'wordlist', 'elective3', 'U6', 'enhance the description', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'wheat', 'n.', '/wiːt/', '小麦', 'In August the golden wheat waves gently in every passing wind.', '八月里,金黄的小麦在每一阵微风中轻轻起伏。', 'First Snow', 18, 0, 'senior', 'wordlist', 'elective3', 'U6', 'golden wheat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gentle', 'adj.', '/ˈdʒentl/', '轻柔的;温和的', 'A gentle wind swept softly across the snowy winter field.', '一阵轻柔的风轻轻拂过雪白的冬日田野。', 'First Snow', 19, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a gentle wind', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sweep', 'v.', '/swiːp/', '吹过;掠过;打扫', 'The cold wind would sweep across the open field all afternoon.', '整个下午,寒风会掠过开阔的田野。', 'First Snow', 20, 0, 'senior', 'wordlist', 'elective3', 'U6', 'sweep across', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ban', 'v.', '/bæn/', '禁止;取缔', 'Silent Spring led many countries to ban the harmful chemical DDT.', '《寂静的春天》促使许多国家禁用有害的化学品 DDT。', 'First Snow', 21, 0, 'senior', 'wordlist', 'elective3', 'U6', 'ban a chemical', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'chorus', 'n.', '/ˈkɔːrəs/', '合唱;齐声;副歌', 'On spring mornings the dawn chorus of birds once filled the quiet woods.', '春天的清晨,鸟儿的黎明合唱曾经回荡在寂静的树林里。', 'First Snow', 22, 0, 'senior', 'wordlist', 'elective3', 'U6', 'the dawn chorus', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dozen', 'num.', '/ˈdʌz(ə)n/', '一打(十二个);许多', 'The book gives dozens of clear examples of harm done to nature.', '这本书给出了几十个对自然造成伤害的清晰例子。', 'First Snow', 23, 0, 'senior', 'wordlist', 'elective3', 'U6', 'dozens of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'thorough', 'adj.', '/ˈθʌrə/', '仔细的;缜密的;彻底的', 'Her long list of sources showed how thorough a scientist she was.', '她长长的资料来源清单显示出她是一位多么缜密的科学家。', 'First Snow', 24, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a thorough scientist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'precise', 'adj.', '/prɪˈsaɪs/', '精确的;一丝不苟的', 'Her research was careful and precise, like that of a true scientist.', '她的研究细致而精确,如同一位真正的科学家。', 'First Snow', 25, 0, 'senior', 'wordlist', 'elective3', 'U6', 'careful and precise', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'launch', 'n.', '/lɔːntʃ/', '发起;推出;启动', 'Silent Spring marked the launch of the green movement in the West.', '《寂静的春天》标志着西方绿色运动的开端。', 'First Snow', 26, 0, 'senior', 'wordlist', 'elective3', 'U6', 'the launch of a movement', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reputation', 'n.', '/ˌrepjʊˈteɪʃ(ə)n/', '名誉;名望;名声', 'Critics tried to damage Carson''s reputation, but she stood firm.', '批评者试图损害卡森的名誉,但她坚定不移。', 'First Snow', 27, 0, 'senior', 'wordlist', 'elective3', 'U6', 'damage one''s reputation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'elegance', 'n.', '/ˈelɪɡəns/', '优美;优雅;简洁', 'The beauty and elegance of her writing reached millions of readers.', '她文字的优美与简洁打动了数百万读者。', 'First Snow', 28, 0, 'senior', 'wordlist', 'elective3', 'U6', 'beauty and elegance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'passionate', 'adj.', '/ˈpæʃ(ə)nət/', '充满激情的;有强烈信念的', 'Readers can still feel the passionate message of her famous warning.', '读者至今仍能感受到她那著名警告中充满激情的讯息。', 'First Snow', 29, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a passionate message', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'diamond', 'n.', '/ˈdaɪəmənd/', '钻石;菱形', 'In the old rhyme the bright star shines like a diamond in the sky.', '在那首古老的童谣里,明亮的星星像钻石一样在天空闪烁。', 'First Snow', 30, 0, 'senior', 'wordlist', 'elective3', 'U6', 'like a diamond', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bloom', 'v.', '/bluːm/', '开花;盛开', 'Spring flowers bloom long after the last winter snow has melted.', '冬天最后一场雪融化很久之后,春花才会盛开。', 'First Snow', 31, 0, 'senior', 'wordlist', 'elective3', 'U6', 'flowers bloom', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'charm', 'n.', '/tʃɑːm/', '魅力;魔力', 'The charms of August come from its contrast with the cold winter.', '八月的魅力来自它与寒冬的对比。', 'First Snow', 32, 0, 'senior', 'wordlist', 'elective3', 'U6', 'the charms of a season', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bleak', 'adj.', '/bliːk/', '阴冷的;荒凉的;阴郁的', 'When the bleak winds of winter blow, we long for warm, sunny days.', '当阴冷的冬风吹起,我们便渴望温暖的晴日。', 'First Snow', 33, 0, 'senior', 'wordlist', 'elective3', 'U6', 'bleak winds', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fade', 'v.', '/feɪd/', '逐渐消失;褪色;凋谢', 'By summer the memory of snow and ice had faded from our minds.', '到了夏天,雪与冰的记忆已从我们脑海中淡去。', 'First Snow', 34, 0, 'senior', 'wordlist', 'elective3', 'U6', 'fade from one''s mind', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'orchard', 'n.', '/ˈɔːtʃəd/', '果园', 'In late summer the orchard is full of trees heavy with ripe fruit.', '夏末的果园里,树木挂满了沉甸甸的成熟果实。', 'First Snow', 35, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a fruit orchard', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cluster', 'n.', '/ˈklʌstə/', '串;丛;簇', 'The branches bent low beneath thick clusters of rich, ripe fruit.', '枝条被一串串丰美成熟的果实压得低垂。', 'First Snow', 36, 0, 'senior', 'wordlist', 'elective3', 'U6', 'clusters of fruit', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pile', 'v.', '/paɪl/', '堆放;摞起', 'The farmers pile the golden wheat into neat and graceful sheaves.', '农民们把金色的麦子堆成整齐而优美的麦束。', 'First Snow', 37, 0, 'senior', 'wordlist', 'elective3', 'U6', 'pile the wheat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tinge', 'v.', '/tɪndʒ/', '使略带色彩;微染', 'The setting sun would tinge the snowy landscape with soft gold.', '落日会把雪景微微染上柔和的金色。', 'First Snow', 38, 0, 'senior', 'wordlist', 'elective3', 'U6', 'tinge with gold', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'wagon', 'n.', '/ˈwæɡən/', '四轮运货车;马车', 'A slow wagon crossed the field, making almost no sound at all.', '一辆缓慢的运货车穿过田野,几乎没有发出任何声响。', 'First Snow', 39, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a slow wagon', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reap', 'v.', '/riːp/', '收割(庄稼)', 'Farmers reap the ripe wheat from the well-cut fields in August.', '八月里,农民们从收割整齐的田地里收割成熟的小麦。', 'First Snow', 40, 0, 'senior', 'wordlist', 'elective3', 'U6', 'reap the wheat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'puzzled', 'adj.', '/ˈpʌz(ə)ld/', '困惑的;无法理解的', 'Many people felt puzzled and worried when the birds suddenly disappeared.', '当鸟儿突然消失时,许多人感到困惑而忧虑。', 'First Snow', 41, 0, 'senior', 'wordlist', 'elective3', 'U6', 'feel puzzled', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'backyard', 'n.', '/ˌbækˈjɑːd/', '后院', 'The feeding stations in the quiet backyards stood empty and still.', '安静后院里的喂食台空荡荡的,一动不动。', 'First Snow', 42, 0, 'senior', 'wordlist', 'elective3', 'U6', 'in the backyard', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tremble', 'v.', '/ˈtremb(ə)l/', '颤抖;发抖', 'The few birds left would tremble violently and could not fly.', '剩下的少数几只鸟剧烈地颤抖,无法飞起。', 'First Snow', 43, 0, 'senior', 'wordlist', 'elective3', 'U6', 'tremble with cold', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fable', 'n.', '/ˈfeɪb(ə)l/', '寓言', 'Carson called her opening chapter ''A Fable for Tomorrow''.', '卡森把她的开篇一章称为《明日寓言》。', 'First Snow', 44, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a fable for tomorrow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'alert', 'v.', '/əˈlɜːt/', '提醒;使(某人)意识到', 'She hoped to alert the public to the damage being done to nature.', '她希望提醒公众注意正在对自然造成的破坏。', 'First Snow', 45, 0, 'senior', 'wordlist', 'elective3', 'U6', 'alert the public', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'marine', 'adj.', '/məˈriːn/', '海洋的', 'Some critics said Carson was only a marine biologist, not a chemist.', '一些批评者说卡森只是个海洋生物学家,而非化学家。', 'First Snow', 46, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a marine biologist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'feather', 'n.', '/ˈfeðə/', '羽毛', 'In the old rhyme the falling snow is like white feathers sent from far away.', '在那首古老的童谣里,落雪如同从远方寄来的白色羽毛。', 'First Snow', 47, 0, 'senior', 'wordlist', 'elective3', 'U6', 'white feathers', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'goose', 'n.', '/ɡuːs/', '鹅', 'A white goose in the yard looked almost invisible against the fresh snow.', '院子里一只白鹅,衬着新雪几乎看不见。', 'First Snow', 48, 0, 'senior', 'wordlist', 'elective3', 'U6', 'a white goose', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u6.01', '①非谓语作定语(the falling snow / the frozen lake / the first to go)', 'A2', 12, '外研社版选择性必修第三册 U6 — 名词与动词是主动/进行关系 → 现在分词(the falling snow);被动/完成关系 → 过去分词(the frozen lake, the branches bent by the snow);表''将要做、可去做''→ 不定式(the first child to see the snow, a place to sit)。', 1, 'elective3', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u6.02', '②非谓语作状语(主动 -ing / 被动 -ed)', 'A2', 12, '外研社版选择性必修第三册 U6 — 分词作状语,其逻辑主语 = 主句主语;主句主语主动发出动作用现在分词(Looking out of the window, I saw …),承受动作用过去分词(Covered with snow, the fields looked white)。', 2, 'elective3', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u6.03', '③非谓语作宾语补足语(see sb doing / find sth done / want sb to do)', 'A2', 12, '外研社版选择性必修第三册 U6 — see/hear/watch/feel/find 等 + 宾语 + 现在分词(动作进行:see sb doing)或过去分词(被动:find sth done);want/ask/tell/expect/cause/force 等 + 宾语 + 不定式 to do。', 3, 'elective3', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The ____ children in the yard threw snowballs at each other.', 'laughing', 'laughed', 'to laugh', 'laugh', 'A', '孩子主动发出''笑''的动作、与名词同时进行 → 现在分词 laughing 作定语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The girl ____ a snowman in the garden waved at us happily.', 'built', 'building', 'to build', 'build', 'B', 'girl 主动''堆''雪人、后带宾语 snowman,主句谓语是 waved → 现在分词 building 作定语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'A boy ____ a snowball at his friend laughed with delight.', 'thrown', 'to throw', 'throwing', 'throw', 'C', 'boy 主动''扔''、带宾语 a snowball → 现在分词 throwing 作定语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The man ____ the snow off his coat smiled at the children.', 'brushed', 'to brush', 'brush', 'brushing', 'D', 'man 主动''拍掉''雪、带宾语,主句谓语 smiled → 现在分词 brushing。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The woman ____ down the lane towards the church looked up at the sky.', 'walking', 'walked', 'to walk', 'walk', 'A', '主句谓语已是 looked,空处只能作定语;woman 主动''走'' → 现在分词 walking。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The lake, ____ solid by the night''s cold, shone like glass in the sun.', 'freezing', 'frozen', 'to freeze', 'freeze', 'B', 'lake 被寒冷''冻结''(by 短语表被动)→ 过去分词 frozen 作定语。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The dining-room window, ____ into a lovely Japanese print, glowed softly.', 'transforming', 'to transform', 'transformed', 'transform', 'C', 'window 被''变成''一幅画(被动)→ 过去分词 transformed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The little plum tree, ____ in soft white snow, stood in full sunlight.', 'wrapping', 'to wrap', 'wrap', 'wrapped', 'D', 'tree 被雪''裹住''(被动)→ 过去分词 wrapped。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The whole village, ____ under a thick white blanket, lay completely silent.', 'hidden', 'hiding', 'to hide', 'hide', 'A', 'village 被雪''藏起''(被动)→ 过去分词 hidden。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The branches, ____ down by the weight of the snow, almost touched the ground.', 'bending', 'bent', 'to bend', 'bend', 'B', 'branches 被雪的重量''压弯''(by 短语表被动)→ 过去分词 bent。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'Leaves ____ to the ground by the cold wind lay frozen on the grass.', 'blowing', 'to blow', 'blown', 'blow', 'C', 'leaves 被风''吹''到地上(by 短语表被动)→ 过去分词 blown。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The garden path, ____ by fresh snow, had completely disappeared by morning.', 'covering', 'to cover', 'cover', 'covered', 'D', 'path 被雪''覆盖''(by 短语表被动)→ 过去分词 covered。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The roofs, ____ thick with heavy snow, looked as if they might break.', 'loaded', 'loading', 'to load', 'load', 'A', 'roofs 被雪''压载''(被动)→ 过去分词 loaded。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The little stream, half ____ by ice, still sang quietly under the trees.', 'blocking', 'blocked', 'to block', 'block', 'B', 'stream 被冰''挡住''(by 短语表被动)→ 过去分词 blocked。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The first child ____ the fresh snow that morning shouted with delight.', 'seeing', 'seen', 'to see', 'saw', 'C', 'the first + 名词后接不定式表''第一个去做……的''→ to see。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'Winter is the best time of year ____ snowballs with your friends.', 'throwing', 'thrown', 'throw', 'to throw', 'D', 'time/the best time 后用不定式表''用来做……的''→ to throw。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'She was the only one ____ outside into the freezing storm.', 'to go', 'going', 'gone', 'went', 'A', 'the only one 后接不定式表''唯一去做……的''→ to go。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'He looked for a quiet place ____ and watch the falling snow.', 'sitting', 'to sit', 'sat', 'sits', 'B', 'a place 后用不定式表''可去做……的地方''→ to sit。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'There was still one more snowy hill ____ before we reached home.', 'climbing', 'climbed', 'to climb', 'climbs', 'C', '名词后接不定式表''尚需去做的''→ one more hill to climb。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.01'), 'The children had a whole free afternoon ____ in the deep fresh snow.', 'playing', 'played', 'plays', 'to play', 'D', 'an afternoon 后用不定式表''用来做……的''→ to play。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ along the snowy lane, I met an old school friend of mine.', 'Walking', 'Walked', 'To walk', 'Walk', 'A', '主句主语 I 主动''走''→ 现在分词 Walking 作状语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ with deep snow, the open fields looked like a vast white sea.', 'Covering', 'Covered', 'To cover', 'Cover', 'B', '主句主语 fields 被雪''覆盖''(被动)→ 过去分词 Covered 作状语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ at the magic world outside, the children talked away excitedly.', 'Looked', 'To look', 'Looking', 'Look', 'C', '主句主语 children 主动''看''→ 现在分词 Looking。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ by the beauty of the first snow, I quite forgot about the cold.', 'Amazing', 'To amaze', 'Amaze', 'Amazed', 'D', '主句主语 I 被景色''打动''(被动)→ 过去分词 Amazed。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ the snow falling steadily outside, we decided to stay at home.', 'Seeing', 'Seen', 'To see', 'See', 'A', '主句主语 we 主动''看见''→ 现在分词 Seeing。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ deep in the snow, the small car simply could not move at all.', 'Burying', 'Buried', 'To bury', 'Bury', 'B', '主句主语 car 被雪''埋住''(被动)→ 过去分词 Buried。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), 'The little boy ran outside, ____ loudly with excitement.', 'shouted', 'to shout', 'shouting', 'shout', 'C', '伴随状语,boy 主动''喊''→ 现在分词 shouting。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ to find the whole world white, I rushed straight to the window.', 'Surprising', 'To surprise', 'Surprise', 'Surprised', 'D', '主句主语 I 感到''惊讶''(被动/情感)→ 过去分词 Surprised。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ warmly in coats and hats, the children went out to play.', 'Dressed', 'Dressing', 'To dress', 'Dress', 'A', '主句主语 children 被''穿戴''好(被动)→ 过去分词 Dressed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ the sharp cold wind on her face, she pulled her coat tighter.', 'Felt', 'Feeling', 'To feel', 'Feel', 'B', '主句主语 she 主动''感到''→ 现在分词 Feeling。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ steadily for several hours, the snow finally stopped around noon.', 'Fallen', 'To fall', 'Falling', 'Fall', 'C', '主句主语 snow 主动''落''、持续进行 → 现在分词 Falling。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ by the warm fire, we watched the snow through the window.', 'Sat', 'To sit', 'Sit', 'Sitting', 'D', '主句主语 we 主动''坐''→ 现在分词 Sitting。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ by the bright morning sun, the snow slowly began to melt.', 'Warmed', 'Warming', 'To warm', 'Warm', 'A', '主句主语 snow 被太阳''晒暖''(by 短语表被动)→ 过去分词 Warmed。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ his cold nose against the glass, the boy watched the white flakes.', 'Pressed', 'Pressing', 'To press', 'Press', 'B', '主句主语 boy 主动''贴''、带宾语 his nose → 现在分词 Pressing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ from the long walk through the snow, they fell asleep at once.', 'Exhausting', 'To exhaust', 'Exhausted', 'Exhaust', 'C', '主句主语 they 感到''精疲力竭''(被动/情感)→ 过去分词 Exhausted。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ the children playing happily below, the old man smiled to himself.', 'Watched', 'To watch', 'Watch', 'Watching', 'D', '主句主语 the old man 主动''看''→ 现在分词 Watching。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ under the deep fresh snow, the narrow garden path was hard to find.', 'Hidden', 'Hiding', 'To hide', 'Hide', 'A', '主句主语 path 被雪''藏住''(被动)→ 过去分词 Hidden。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ slowly down from the grey sky, the snowflakes covered everything.', 'Drifted', 'Drifting', 'To drift', 'Drift', 'B', '主句主语 snowflakes 主动''飘落''→ 现在分词 Drifting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ at the falling snow, he suddenly remembered a rhyme from childhood.', 'Gazed', 'To gaze', 'Gazing', 'Gaze', 'C', '主句主语 he 主动''凝视''→ 现在分词 Gazing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.02'), '____ tightly in a warm scarf, she stepped out into the winter storm.', 'Wrapping', 'To wrap', 'Wrap', 'Wrapped', 'D', '主句主语 she 被围巾''裹住''(被动)→ 过去分词 Wrapped。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'From my study I can see the children ____ their noses against the window.', 'flattening', 'flattened', 'to flatten', 'flatten', 'A', 'see + 宾语 children + 主动且进行的动作(带宾语 noses)→ 现在分词 flattening 作宾补。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'We watched the soft snow ____ quietly past the bright street lamp.', 'fallen', 'falling', 'to fall', 'fall', 'B', 'watch + 宾语 snow + 正在进行的动作 → 现在分词 falling 作宾补。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'All night I could hear the cold wind ____ around the old empty house.', 'blown', 'to blow', 'blowing', 'blow', 'C', 'hear + 宾语 wind + 主动进行的动作 → 现在分词 blowing 作宾补。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'She saw her little brother ____ a snowball at the front door.', 'thrown', 'to throw', 'throw', 'throwing', 'D', 'see + 宾语 brother + 主动且带宾语的动作 → 现在分词 throwing 作宾补。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'Through the window we watched the children ____ happily in the deep snow.', 'playing', 'played', 'to play', 'play', 'A', 'watch + 宾语 children + 正在进行的动作 → 现在分词 playing 作宾补。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'I noticed the bare plum tree ____ gently in the cold winter wind.', 'bent', 'bending', 'to bend', 'bend', 'B', 'notice + 宾语 tree + 主动进行的动作 → 现在分词 bending 作宾补。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'He could feel the soft snowflakes ____ on his warm red cheeks.', 'melted', 'to melt', 'melting', 'melt', 'C', 'feel + 宾语 snowflakes + 正在进行的动作 → 现在分词 melting 作宾补。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'When I woke up, I found the whole garden ____ in deep white snow.', 'burying', 'to bury', 'bury', 'buried', 'D', 'find + 宾语 garden + 被动状态(被雪埋)→ 过去分词 buried 作宾补。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'We found the small pond completely ____ over by early next morning.', 'frozen', 'freezing', 'to freeze', 'freeze', 'A', 'find + 宾语 pond + 被动状态(被冻住)→ 过去分词 frozen 作宾补。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'I saw the dining-room window ____ into a lovely Japanese print.', 'transforming', 'transformed', 'to transform', 'transform', 'B', 'see + 宾语 window + 被动结果(被变成)→ 过去分词 transformed 作宾补。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'She found her warm gloves ____ somewhere under the deep snow.', 'losing', 'to lose', 'lost', 'lose', 'C', 'find + 宾语 gloves + 被动状态(被弄丢)→ 过去分词 lost 作宾补。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'We saw several thin branches ____ by the great weight of the snow.', 'breaking', 'to break', 'break', 'broken', 'D', 'see + 宾语 branches + 被动结果(被压断,by 短语)→ 过去分词 broken 作宾补。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'He wanted the snowy path ____ before the guests finally arrived.', 'cleared', 'clearing', 'to clear', 'clear', 'A', 'want + 宾语 path + 被动(路被清理)→ 过去分词 cleared 作宾补。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'By noon we found most of the snow ____ away by the warm bright sun.', 'melting', 'melted', 'to melt', 'melt', 'B', 'find + 宾语 snow + 被动结果(被晒化,by 短语)→ 过去分词 melted 作宾补。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'My mother told us ____ our wet boots before coming back inside.', 'cleaning', 'cleaned', 'to clean', 'clean', 'C', 'tell sb to do sth → 宾补用不定式 to clean。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'The freezing weather caused the whole lake ____ hard overnight.', 'freezing', 'frozen', 'freeze', 'to freeze', 'D', 'cause sth to do sth → 宾补用不定式 to freeze。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'We expected the heavy snow ____ for several more cold days.', 'to last', 'lasting', 'lasted', 'last', 'A', 'expect sth to do sth → 宾补用不定式 to last。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'The teacher asked the children ____ quietly at the falling snow.', 'looking', 'to look', 'looked', 'look', 'B', 'ask sb to do sth → 宾补用不定式 to look。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'I would like you ____ this old winter rhyme together with me.', 'repeating', 'repeated', 'to repeat', 'repeat', 'C', 'would like sb to do sth → 宾补用不定式 to repeat。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U6' AND code='fe3u6.03'), 'The deep snow forced many drivers ____ their cars at home that day.', 'leaving', 'left', 'leave', 'to leave', 'D', 'force sb to do sth → 宾补用不定式 to leave。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Magic of the First Snow', 'You go to bed in one ordinary world and wake up the next morning in a completely different one. That is the strange magic of the first snow of winter. When it falls quietly during the night, no one hears a sound, yet by dawn the whole garden has been changed. The grass, the paths and the roofs all lie hidden under a soft white blanket. Many writers have described this feeling of wonder. Some say that for certain quiet people, even a slight fall of snow is a real event, worth remembering for years. Children press their faces to the cold window and talk excitedly, as if a holiday had suddenly arrived. Grown-ups, too, often feel like children again. The very quietness and secrecy of the snow seem to make it more magical, and for a short while the busy, familiar world feels brand new and full of pleasant surprise.', '说明·初雪的奇妙', 151, '[{"q":"What makes the first snow feel so magical, according to the text?","answer":"A","options":["The quiet, secret way it changes the world overnight.","The loud noise it makes as it falls.","The fact that it never melts away.","The money that people can earn from it."],"explanation":"末段''quietness and secrecy of the snow… make it more magical''的转述。"},{"q":"How do the children in the passage react to the snow?","answer":"B","options":["They calmly ignore it.","They press to the window and talk with great excitement.","They feel frightened and start to cry.","They go straight back to sleep."],"explanation":"原文''press their faces to the cold window and talk excitedly''的转述。"},{"q":"What does the passage suggest about grown-ups and the first snow?","answer":"A","options":["They can feel young again, like children.","They never even notice it.","They only worry about the cold.","They must go to work as usual."],"explanation":"原文''Grown-ups, too, often feel like children again''的转述。"}]'::jsonb, '[{"word":"secrecy","cn":"隐秘"},{"word":"hidden","cn":"被藏起的"}]'::jsonb, 2, 'elective3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Winter Morning Changes', 'On the morning after the first snow, the world outside kept changing hour by hour. When the writer first got up, everything looked cold and pale, a place of dead white and soft blue. The light coming through the windows was so strange that even washing and dressing felt unfamiliar. Then the sun rose, and its warm rays began to flush the snow with delicate pink, turning the view into something like a beautiful painting. An hour or two later the scene changed once more: the gentle pink had gone, and everything became a cold sparkle of white and blue. By the afternoon the snow was falling again in great soft flakes, so thick that he could hardly see across the shallow valley. The roofs grew heavy, and the trees began to bend low under the weight. The same quiet garden had worn three or four different faces in a single winter morning.', '记叙·冬晨光影的变化', 153, '[{"q":"How did the world look when the writer first got up?","answer":"B","options":["Bright green and warm.","Cold and pale, all white and blue.","Dark, with heavy rain falling.","Exactly the same as every other day."],"explanation":"原文''cold and pale, a place of dead white and soft blue''的转述。"},{"q":"What happened to the snow when the sun rose?","answer":"C","options":["It melted all at once.","It made the sky turn black.","It turned a soft pink colour.","It started a heavy storm."],"explanation":"原文''flush the snow with delicate pink''的转述。"},{"q":"What was the weather doing by the afternoon?","answer":"D","options":["The snow had stopped completely.","Rain had replaced the snow.","The sun shone brightly all day.","Snow was falling thickly in large flakes."],"explanation":"原文''snow was falling again in great soft flakes''的转述。"}]'::jsonb, '[{"word":"flush","cn":"使发红"},{"word":"sparkle","cn":"闪光"}]'::jsonb, 2, 'elective3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Snow Memory from Childhood', 'Whenever heavy snow falls, an old man named Tom remembers a winter morning from long ago. As a boy, he would flatten his small nose against the cold window and watch the white flakes come slowly down. While he watched, he liked to repeat a funny little rhyme about snow that his grandmother had taught him. In the rhyme, the falling snow was compared to soft white feathers sent down from far away. To Tom, the snow seemed to fall faster each time he said the words aloud. Those mornings felt full of innocent happiness, with no worries about school or time. Now, many years later, the same rhyme still runs through his head when he sees the first snow. It brings back the warm kitchen, his grandmother''s gentle voice and the bright wonder he felt as a child. A short childhood rhyme, he says, can keep a whole winter alive in the memory.', '记叙·童年的雪忆', 154, '[{"q":"What did Tom do as a boy when it snowed?","answer":"A","options":["He pressed his nose to the window and watched the flakes.","He stayed in bed and slept.","He ran outside without any coat.","He read science books all morning."],"explanation":"原文''flatten his small nose against the cold window and watch''的转述。"},{"q":"What was the snow compared to in the rhyme?","answer":"B","options":["Tiny pieces of broken glass.","Soft white feathers from far away.","Drops of warm summer rain.","Grains of golden wheat."],"explanation":"原文''compared to soft white feathers sent down from far away''的转述。"},{"q":"Why is the old rhyme important to Tom now?","answer":"C","options":["It teaches him modern science.","It helps him earn extra money.","It brings back happy childhood memories.","It tells him tomorrow''s weather."],"explanation":"末段''brings back the warm kitchen… the bright wonder he felt as a child''的转述。"}]'::jsonb, '[{"word":"rhyme","cn":"童谣"},{"word":"innocent","cn":"天真的"}]'::jsonb, 2, 'elective3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'How Snowflakes Are Made', 'Have you ever looked closely at a single snowflake before it melts on your glove? Each one begins high up in the cold clouds, where tiny drops of water freeze around specks of dust. As the ice slowly grows, it forms a small crystal with six sides. No two snowflakes are ever exactly the same, because each one falls through slightly different air on its long way to the ground. When the air is very cold and still, the flakes stay small and dry, and they sparkle like tiny diamonds. When it is a little warmer, they join together into the great soft flakes that children love to catch. Although a single flake weighs almost nothing at all, billions of them together can cover a whole town, bend the branches of trees and hide the streets. The next time it snows, try to catch one flake on your dark glove and look at its beautiful, secret shape before it disappears.', '说明·雪花的形成', 160, '[{"q":"Where does a snowflake first begin to form?","answer":"D","options":["On the warm ground.","Deep down in the ocean.","Inside a warm house.","Inside cold clouds, around tiny specks of dust."],"explanation":"原文''begins high up in the cold clouds, where tiny drops of water freeze around specks of dust''的转述。"},{"q":"Why are no two snowflakes exactly alike?","answer":"A","options":["Every flake passes through air that keeps changing.","They are all made by machines.","People paint them by hand.","They never actually fall."],"explanation":"原文''each one falls through slightly different air''的转述。"},{"q":"What can billions of snowflakes together do?","answer":"B","options":["Disappear before they ever land.","Cover a town and weigh down branches.","Make the winter air much warmer.","Turn into rain at once."],"explanation":"原文''cover a whole town, bend the branches of trees and hide the streets''的转述。"}]'::jsonb, '[{"word":"flake","cn":"雪片"},{"word":"crystal","cn":"晶体"}]'::jsonb, 2, 'elective3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'How Animals Survive the Snow', 'Winter is a hard season for the animals that live in cold lands, yet many of them have clever ways to survive the snow. Some birds fly thousands of miles to warmer places before the first frost arrives, and they return only when spring flowers bloom again. Others stay behind and grow thicker feathers to keep out the bleak wind. Certain small animals, such as mice, dig narrow tunnels beneath the snow, where the air is surprisingly warm and still. A few large animals, like bears, eat as much as they can in autumn and then sleep deeply through the coldest months. Even under a frozen pond, fish can go on living quietly in the water below the ice. Without these clever tricks, few creatures could face the long, dark winter. When the snow finally melts and the warm sun returns, the whole world seems to wake up and come alive once more.', '说明·动物如何过冬', 153, '[{"q":"What do some birds do before winter arrives?","answer":"C","options":["They stop eating completely.","They dig tunnels under the snow.","They fly far away to warmer places.","They sleep through the whole winter."],"explanation":"原文''fly thousands of miles to warmer places before the first frost''的转述。"},{"q":"How do small animals like mice survive the cold?","answer":"D","options":["They grow much larger.","They fly south with the birds.","They live inside frozen ponds.","They make warm tunnels beneath the snow."],"explanation":"原文''dig narrow tunnels beneath the snow, where the air is surprisingly warm''的转述。"},{"q":"What does the passage say about bears?","answer":"A","options":["They eat a lot in autumn, then sleep through the cold.","They never sleep at all in winter.","They grow brand new feathers.","They swim about under the ice."],"explanation":"原文''eat as much as they can in autumn and then sleep deeply through the coldest months''的转述。"}]'::jsonb, '[{"word":"frost","cn":"霜冻"},{"word":"bleak","cn":"阴冷的"}]'::jsonb, 2, 'elective3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Book That Woke the World', 'In 1962 a scientist named Rachel Carson published a book called Silent Spring, and it changed the way people think about nature. The book opens by imagining a quiet town where, one spring, no birds sing at all. The feeding places in the backyards stand empty, and the few birds left tremble and cannot fly. Carson used this sad picture to alert ordinary people, not just scientists, to the harm that certain chemicals were doing to living things. Her research was careful and precise, and a long list of sources showed how thorough she had been. Some companies attacked her and tried to damage her reputation, saying she was only a marine biologist. Yet most scientists supported her, and the beauty and elegance of her writing reached millions of readers. In the end, the harmful chemical she warned about was banned in many countries. People still feel the passionate message of her famous book today.', '议论·《寂静的春天》', 155, '[{"q":"How does the book Silent Spring begin?","answer":"B","options":["With a long list of chemical names.","By imagining a spring with no singing birds.","With a happy story about farming.","By describing a snowy winter scene."],"explanation":"原文''imagining a quiet town where, one spring, no birds sing at all''的转述。"},{"q":"Why did some companies attack Carson?","answer":"C","options":["Because her book had harmed nature.","Because she could not write well at all.","Because they wanted to stop her warning and hurt her good name.","Because she was a famous singer."],"explanation":"原文''tried to damage her reputation''的转述。"},{"q":"What finally happened because of the book?","answer":"D","options":["All the birds disappeared forever.","Carson stopped writing for good.","Nothing at all changed.","Many countries decided to stop using the harmful chemical."],"explanation":"原文''the harmful chemical she warned about was banned in many countries''的转述。"}]'::jsonb, '[{"word":"alert","cn":"提醒"},{"word":"reputation","cn":"名誉"}]'::jsonb, 2, 'elective3', 'U6', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U6', 'The First Snow of the Year', 'Last night the first snow of the year fell while everyone was fast asleep. When I (1)____ up this morning, the whole world outside had turned white. The garden, the path and the roofs were all (2)____ under a soft blanket of snow. I pressed my nose against the cold (3)____ and watched the flakes drift slowly down. Everything was so (4)____ that I could hardly hear a single sound. My little sister was so (5)____ that she shouted and ran from room to room. We quickly put on our warm coats and (6)____ outside to play. The snow felt cold and (7)____ on my face. We rolled it into a big ball to build a (8)____. By lunchtime our cheeks were red and our hands were (9)____, but we did not want to go inside. The first snow had turned an ordinary day into something truly (10)____.', 148, 2, '[{"q":"1","answer":"A","options":["woke","sold","lost","threw"],"explanation":"wake up 醒来 → woke。"},{"q":"2","answer":"B","options":["sold","hidden","bought","broken"],"explanation":"be hidden under snow 被雪盖住。"},{"q":"3","answer":"C","options":["river","market","window","forest"],"explanation":"press one''s nose against the window 贴着窗户。"},{"q":"4","answer":"D","options":["loud","warm","busy","quiet"],"explanation":"so quiet 太安静,几乎听不到声音。"},{"q":"5","answer":"A","options":["excited","bored","tired","angry"],"explanation":"so excited 太兴奋,又叫又跑。"},{"q":"6","answer":"B","options":["refused","rushed","failed","forgot"],"explanation":"rushed outside to play 冲出去玩。"},{"q":"7","answer":"C","options":["hot","heavy","soft","sharp"],"explanation":"cold and soft on my face 又冷又软。"},{"q":"8","answer":"D","options":["sandcastle","fire","boat","snowman"],"explanation":"build a snowman 堆雪人。"},{"q":"9","answer":"A","options":["freezing","boring","exciting","amazing"],"explanation":"hands were freezing 手冻僵了。"},{"q":"10","answer":"B","options":["ordinary","magical","boring","normal"],"explanation":"something truly magical 真正神奇。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U6', 'Building a Snowman', 'On Saturday morning my friends and I decided to build a (1)____ in the park. First, we rolled a small ball of snow along the ground until it grew big and (2)____. This became the body. Then we made a smaller ball for the (3)____ and lifted it carefully on top. We used two black stones for the eyes and a long orange carrot for the (4)____. My friend Lily found some thin branches and pushed them in for the (5)____, so the snowman could seem to wave. It was hard (6)____, and soon our gloves were wet and cold. But none of us wanted to (7)____ until it was finished. When at last our snowman was (8)____, we stepped back and looked at it with (9)____. It seemed to smile at us under the grey winter sky. We took a photo so that we could (10)____ that happy morning for years.', 152, 2, '[{"q":"1","answer":"C","options":["sandcastle","garden","snowman","market"],"explanation":"build a snowman 堆雪人。"},{"q":"2","answer":"D","options":["square","flat","thin","round"],"explanation":"big and round 又大又圆。"},{"q":"3","answer":"A","options":["head","foot","river","roof"],"explanation":"a smaller ball for the head 做头。"},{"q":"4","answer":"B","options":["ear","nose","hand","door"],"explanation":"a carrot for the nose 当鼻子。"},{"q":"5","answer":"C","options":["wheels","wings","arms","books"],"explanation":"branches for the arms 当手臂。"},{"q":"6","answer":"D","options":["weather","money","music","work"],"explanation":"hard work 累活儿。"},{"q":"7","answer":"A","options":["stop","sleep","sing","swim"],"explanation":"did not want to stop 不想停下。"},{"q":"8","answer":"B","options":["absent","ready","empty","asleep"],"explanation":"the snowman was ready 雪人做好了。"},{"q":"9","answer":"C","options":["fear","anger","pride","sadness"],"explanation":"look at it with pride 自豪地看。"},{"q":"10","answer":"D","options":["forget","lose","sell","remember"],"explanation":"remember that morning 记住那个早晨。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U6', 'A Walk in the Snow', 'One cold afternoon I went for a quiet (1)____ along the river near my home. Snow was (2)____ softly from the grey sky, and the whole path lay white and silent. My boots made a soft sound as they (3)____ through the fresh snow. The trees on both sides were (4)____ low under the heavy white weight. Here and there a brave little bird sat on a branch, its (5)____ puffed up against the cold. I felt the sharp wind (6)____ across the open field and pulled my scarf tighter. Although my fingers were (7)____, my heart felt warm and calm. The river was half (8)____ with ice, but I could still hear it singing quietly underneath. I stood for a long time, simply (9)____ at the beautiful winter scene. That peaceful walk in the snow is something I will always (10)____.', 142, 2, '[{"q":"1","answer":"A","options":["walk","sleep","race","meal"],"explanation":"go for a walk 散步。"},{"q":"2","answer":"B","options":["rising","falling","growing","shining"],"explanation":"snow was falling 雪在落。"},{"q":"3","answer":"C","options":["swam","climbed","sank","flew"],"explanation":"boots sank through the snow 靴子陷进雪里。"},{"q":"4","answer":"D","options":["growing","jumping","dancing","bending"],"explanation":"trees bending low 树被压弯。"},{"q":"5","answer":"A","options":["feathers","wheels","leaves","stones"],"explanation":"its feathers puffed up 羽毛蓬起御寒。"},{"q":"6","answer":"B","options":["sleep","sweep","cook","read"],"explanation":"feel the wind sweep across 风掠过。"},{"q":"7","answer":"C","options":["boring","smiling","freezing","sleeping"],"explanation":"fingers were freezing 手指冻僵。"},{"q":"8","answer":"D","options":["filled","sold","opened","covered"],"explanation":"half covered with ice 半被冰覆盖。"},{"q":"9","answer":"A","options":["gazing","shouting","running","eating"],"explanation":"simply gazing at the scene 凝望雪景。"},{"q":"10","answer":"B","options":["forget","remember","lose","doubt"],"explanation":"always remember 永远记得。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U6', 'Grandfather''s Winter Rhyme', 'When I was small, my (1)____ taught me a funny little rhyme about the snow. Every winter, when the first flakes began to (2)____, he would sit me by the warm (3)____ and say the words slowly. In the rhyme, the snow was like white (4)____ falling from the sky. I thought the snow fell (5)____ each time we repeated it together. Those quiet evenings felt full of (6)____ joy, with no worries at all. Now my grandfather is very old, and his voice has grown (7)____. But whenever I see the first snow, the same old rhyme still runs through my (8)____. It always (9)____ back the warm kitchen and his kind smile. A short, simple rhyme, I have learned, can keep a happy (10)____ alive for a whole lifetime.', 131, 2, '[{"q":"1","answer":"C","options":["stranger","customer","grandfather","waiter"],"explanation":"下文''my grandfather is very old'',故 grandfather。"},{"q":"2","answer":"D","options":["melt","grow","sail","fall"],"explanation":"the first flakes began to fall 开始落下。"},{"q":"3","answer":"A","options":["fire","river","window","market"],"explanation":"by the warm fire 在温暖的炉火旁。"},{"q":"4","answer":"B","options":["stones","feathers","wheels","coins"],"explanation":"snow was like white feathers 雪像白羽毛。"},{"q":"5","answer":"C","options":["slower","higher","faster","later"],"explanation":"snow fell faster 雪下得更快。"},{"q":"6","answer":"D","options":["angry","boring","painful","innocent"],"explanation":"innocent joy 天真的快乐。"},{"q":"7","answer":"A","options":["weak","loud","fast","sharp"],"explanation":"his voice has grown weak 声音变弱。"},{"q":"8","answer":"B","options":["hand","head","foot","door"],"explanation":"run through my head 在脑海回响。"},{"q":"9","answer":"C","options":["sells","breaks","brings","loses"],"explanation":"brings back the warm kitchen 唤回回忆。"},{"q":"10","answer":"D","options":["machine","market","mistake","memory"],"explanation":"keep a happy memory alive 留住美好回忆。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U6', 'Why I Love Winter', 'Many people complain about the cold, but winter is my favourite (1)____ of the year. I love the morning when I wake up and (2)____ that the world has turned white overnight. The snow makes even an ordinary street look clean and (3)____. On winter days my family likes to stay (4)____ together, sitting by the fire and drinking something hot. Outside, children (5)____ snowballs and laugh until their cheeks turn red. When the sun comes out, the snow (6)____ like thousands of tiny diamonds. In the evening, the air is so (7)____ that you can see your own breath. Of course, winter does not (8)____ forever, and soon the snow will melt and flowers will (9)____ again. But that is exactly why each first snow feels so special. I will always (10)____ the quiet magic of the winter months.', 140, 2, '[{"q":"1","answer":"A","options":["season","machine","market","subject"],"explanation":"my favourite season 最爱的季节。"},{"q":"2","answer":"B","options":["sell","find","lose","forget"],"explanation":"wake up and find 醒来发现。"},{"q":"3","answer":"C","options":["ugly","dirty","beautiful","noisy"],"explanation":"clean and beautiful 干净美丽。"},{"q":"4","answer":"D","options":["outside","asleep","awake","inside"],"explanation":"stay inside by the fire 待在屋里。"},{"q":"5","answer":"A","options":["throw","eat","read","sing"],"explanation":"throw snowballs 扔雪球。"},{"q":"6","answer":"B","options":["melts","sparkles","falls","breaks"],"explanation":"snow sparkles like diamonds 雪像钻石般闪耀。"},{"q":"7","answer":"C","options":["warm","wet","cold","sweet"],"explanation":"so cold you can see your breath 太冷能看到呵气。"},{"q":"8","answer":"D","options":["win","lose","open","last"],"explanation":"winter does not last forever 冬天不会永远持续。"},{"q":"9","answer":"A","options":["bloom","freeze","fall","fade"],"explanation":"flowers will bloom 花会开。"},{"q":"10","answer":"B","options":["forget","remember","doubt","hide"],"explanation":"always remember 永远记得。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U6', 'Caring for Birds in Winter', 'Winter can be a very hard time for the small (1)____ that stay near our homes. When deep snow (2)____ the ground, they cannot easily find seeds or insects to eat. Many of them grow weak, and some even (3)____ from cold and hunger. Luckily, there is a simple way we can (4)____ them. We can hang a small feeder in the (5)____ and fill it with seeds and nuts. On the coldest days, a dish of clean (6)____ is just as important, because frozen ponds give the birds nothing to drink. If we are (7)____ and kind, the garden will soon be full of busy wings and cheerful (8)____. Watching them through the window is a real (9)____ on a grey winter morning. By caring for these little creatures, we help to (10)____ the natural world we all share.', 140, 2, '[{"q":"1","answer":"C","options":["cars","shops","birds","books"],"explanation":"small birds 小鸟。"},{"q":"2","answer":"D","options":["sells","opens","breaks","covers"],"explanation":"snow covers the ground 雪盖住地面。"},{"q":"3","answer":"A","options":["die","win","read","drive"],"explanation":"some even die from cold and hunger 因冷饿而死。"},{"q":"4","answer":"B","options":["sell","help","forget","lose"],"explanation":"a way we can help them 帮助它们。"},{"q":"5","answer":"C","options":["ocean","classroom","backyard","station"],"explanation":"hang a feeder in the backyard 挂在后院。"},{"q":"6","answer":"D","options":["smoke","sand","paper","water"],"explanation":"a dish of clean water 一碟干净水。"},{"q":"7","answer":"A","options":["patient","lazy","rude","careless"],"explanation":"patient and kind 有耐心又善良。"},{"q":"8","answer":"B","options":["prices","songs","machines","mistakes"],"explanation":"cheerful songs 欢快的鸟鸣。"},{"q":"9","answer":"C","options":["problem","mistake","pleasure","danger"],"explanation":"a real pleasure 真正的乐趣。"},{"q":"10","answer":"D","options":["sell","harm","forget","protect"],"explanation":"help to protect the natural world 保护自然。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·对话 Waking Up to the First Snow', '外研社版选择性必修第三册 U6 · dialogue', 3, 'Anna: Ben, wake up! Come and look out of the window!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·短文 How the First Snow Feels', '外研社版选择性必修第三册 U6 · passage', 2, 'The first snow of winter often falls quietly during the night.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·对话 Walking to School in the Snow', '外研社版选择性必修第三册 U6 · dialogue', 3, 'Tom: Be careful, Lucy. The path is covered with ice this morning.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·短文 Snowflakes', '外研社版选择性必修第三册 U6 · passage', 2, 'Have you ever looked closely at a single snowflake?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·对话 Caring for Birds in Winter', '外研社版选择性必修第三册 U6 · dialogue', 3, 'Emma: Grandpa, why are you hanging that little box on the tree?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U6 听力·短文 A Book That Changed Minds', '外研社版选择性必修第三册 U6 · passage', 2, 'In 1962 a scientist named Rachel Carson wrote a famous book.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Describe the First Snow(描写初雪)', 'The First Snow', '假设你叫李华。上周你的城市迎来了今年的第一场雪。请用英语写一篇约100词的短文,描写初雪的景象和你的感受,内容包括:① 你早上醒来看到的雪景;② 你和家人或朋友做的一件事;③ 初雪带给你的感受。注意:适当使用非谓语动词作定语、状语或补语(如 the falling snow / Looking out of the window, I … / I saw the children playing)。', 'Suppose you are Li Hua. Last week your city had its first snow of the year. Write a short passage of about 100 words describing the first snow and your feelings, including: 1) the snowy scene you saw when you woke up; 2) one thing you did with your family or friends; 3) how the first snow made you feel. Try to use non-finite verbs as attributive, adverbial or complement (e.g. the falling snow / Looking out of the window, I … / I saw the children playing).', '["描写雪景(定语非谓语:the falling snow / the snow-covered roofs)","用分词状语开头(Looking out of the window, I saw …)","用补语结构(I saw the children playing / found the garden covered)","表达真实感受 + 句子地道连贯、代词指代清楚"]'::jsonb, 70, 100, 'Last Wednesday I woke up to find the whole world turned white. Looking out of the window, I saw soft snow falling quietly past the glass. The garden, the roofs and the old plum tree were all covered in a thick white blanket. Excited by the magical scene, my sister and I quickly got dressed and rushed outside. We rolled the fresh snow into a big ball and built a cheerful snowman, laughing until our cheeks turned red. Standing in the falling snow, I felt as happy and free as a little child. The first snow had truly turned an ordinary morning into something magical.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Looking out of the window, I saw soft snow falling quietly past the glass.","The roofs and trees were all covered in a thick white blanket.","Excited by the magical scene, my sister and I rushed straight outside.","Standing in the falling snow, I felt as happy as a little child."]'::jsonb, '[{"wrong":"Look out of the window, I saw the snow.","correct":"Looking out of the window, I saw the snow.","note":"主句主语 I 与 look 是主动关系,状语用现在分词 Looking。"},{"wrong":"The garden was cover with snow.","correct":"The garden was covered with snow.","note":"garden 被雪覆盖,被动用过去分词 covered。"},{"wrong":"I saw the children played in the snow.","correct":"I saw the children playing in the snow.","note":"see sb doing:动作正在进行用现在分词 playing,不用过去式。"}]'::jsonb, '【初雪描写结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U6', '{"title":"非谓语动词作定语·状语·补语 速查","intro":"非谓语动词(doing / done / to do)没有时态人称变化,靠「主动还是被动」「进行还是完成」「将来还是已发生」来选形式。口诀:自己主动做→doing,被别人做(被动)→done,将要去做→to do。","table":{"headers":["位置 / 功能","怎么选","例句"],"rows":[["定语 -ing(主动·进行)","名词自己发出动作","the falling snow 纷飞的雪 / the running water"],["定语 -ed(被动·完成)","名词承受动作","the frozen lake 结冰的湖 / branches bent by the snow"],["定语 to do(将来·要做)","表''将要做、可去做的''","the first child to see the snow / a place to sit"],["状语 -ing / -ed","看主句主语:主动用 -ing,被动用 -ed","Looking out, I saw … / Covered with snow, the fields …"],["补语 doing / done","see/hear/find/watch + 宾语:进行用 doing,被动用 done","I saw the children flattening … / found the garden covered"],["补语 to do","want/ask/tell/expect + 宾语 + to do","I want you to repeat the rhyme"]]},"specialRules":[{"rule":"定语:名词与动词是主动/进行关系 → -ing;被动/完成关系 → -ed","mark":"the falling snow ✓ / the fallen leaves(已落下)"},{"rule":"状语:分词的逻辑主语 = 主句主语;主动 -ing,被动 -ed","mark":"Covered with snow, the field looked white(field 被覆盖)"},{"rule":"see/hear/watch/feel/find + 宾语 + doing(进行)或 done(被动)","mark":"see sb doing / find sth done"},{"rule":"want/ask/tell/expect/cause/force + 宾语 + 不定式 to do","mark":"ask sb to do;to do 也常作定语表''将要做的''"}],"why":["非谓语动词其实是把一个动作''压缩''进句子里:作定语时它相当于一个定语从句的简化(the snow that is falling → the falling snow);作状语时相当于一个时间/原因状语从句的简化;作补语时补充说明宾语在''做什么''或''被怎样''。判断核心永远是:这个名词/宾语是主动做,还是被动承受。"],"gaokaoPoints":["语法填空高频:给动词原形,判断填 doing / done / to do —— 先看它与所修饰名词是主动还是被动。","读后续写/状语题:分词作状语时,逻辑主语必须与主句主语一致,主动 -ing、被动 -ed。","see/hear/find + 宾语 + 补语:动作进行用 doing,被动用 done(I saw the children playing / found the garden covered)。"],"examVsReal":[{"exam":"Looking out of the window, I saw the snow.(书面分词状语)","real":"I looked out of the window and saw the snow.","note":"口语更爱用并列句;书面写作偏爱分词状语,更简洁地道。"},{"exam":"the falling snow(分词作定语)","real":"the snow that was falling","note":"分词定语 = 定语从句的简化,书面表达更紧凑。"}]}'::jsonb, 'fltrp');
